import Dates from '@/src/services/dates/Dates.service.ts';
import { ddChar } from '@/src/services/dates/types.ts';

import I from '../types.ts';

const regsMonthDateValidate: I['regsMonthDateValidate'] = function ({ value }) {
    const { datePast, dateFuture } = this.props;
    const dateArr = value.split(ddChar);
    const [month, year] = dateArr;

    if (month && !Number.isNaN(+month)) {
        if (+month === 0) {
            dateArr[0] = '01';
        }

        if (+month > 12) {
            dateArr[0] = '12';
        }
    }

    if (year && !Number.isNaN(+year)) {
        if (+year < 1950) {
            dateArr[1] = '1950';
        }

        if (+year > 2150) {
            dateArr[1] = '2150';
        }
    }

    let resultValue = dateArr.join(ddChar);

    if (datePast === false) {
        const date = new Dates().convertFromString(resultValue);

        if (date && date.getTime() < new Date().getTime()) {
            resultValue = new Dates().format(new Date().getTime(), {});
        }
    }

    if (dateFuture === false) {
        const date = new Dates().convertFromString(resultValue);

        if (date && date.getTime() > new Date().getTime()) {
            resultValue = new Dates().format(new Date().getTime(), {});
        }
    }

    return { value: resultValue };
};

export default regsMonthDateValidate;
