import { ddChar } from '@/src/services/dates/types';

const regs = {
    any: {
        template: '',
        emptyChar: '_',
        regExp: /\D/gi,
    },
    date: {
        template: `__${ddChar}__${ddChar}____`,
        emptyChar: '_',
        regExp: /\D/gi,
    },
    monthDate: {
        template: `__${ddChar}____`,
        emptyChar: '_',
        regExp: /\D/gi,
    },
    time: {
        template: `__:__`,
        emptyChar: '_',
        regExp: /\D/gi,
    },
    dateAndTime: {
        template: `__${ddChar}__${ddChar}____ в __:__`,
        emptyChar: '_',
        regExp: /\D/gi,
    },
};

type RegsT = {
    template: string;
    emptyChar: string;
    regExp: RegExp;
    notAddChars?: {
        start: number;
        end: number;
        startChar: string;
        chars: readonly string[];
    };
};

export default regs;

export type { RegsT };
